contracts/BohriumMining.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";

interface IBohriumToken {
    function mint(address to, uint256 amount) external;
}

interface IStakedBohrToken is IERC20 {
    function getEffectiveBalance(address account) external view returns (uint256);
    function delegatedBy(address account) external view returns (address);
}

contract BohriumMining is Ownable {
    IBohriumToken public bohriumToken;
    IStakedBohrToken public stakedBohrToken;

    uint256 public constant INITIAL_REWARD = 10 * 10**18;       // 10 BOHR initial reward
    uint256 public constant HALVING_INTERVAL_BLOCKS = 262800;          // Number of blocks in a year with 2-minute blocks
    uint256 public constant TARGET_BLOCK_TIME = 120 seconds;    // 2 minutes target block time
    uint8 public constant DIFFICULTY_ADJUSTMENT_BLOCKS = 5;     // Adjust difficulty every 5 blocks
    uint8 public constant REQUIRED_STAKE_MULTIPLIER = 10;       // Must stake 10x reward to avoid penalty
    uint8 public constant UNDERSTAKE_PENALTY_MULTIPLIER = 2;    // 2x harder difficulty if under required stake

    // Additional state variables
    uint256 public baseDifficulty;
    uint256 public lastHalvingTimestamp;
    uint256 public lastBlockTimestamp;
    uint256 public blockHeight;
    bytes32 public lastBlockHash;
    uint256 public adjustmentStartTimestamp;

    event BlockMined(
        address indexed miner,
        uint256 indexed blockHeight,
        uint256 nonce,
        uint256 reward,
        uint256 timeTaken,
        address rewardRecipient
    );
    event DifficultyAdjusted(uint256 newDifficulty);
    event RewardHalved(uint256 newReward);

    // Event for parameter changes
    event MiningParamsChanged(
        uint256 indexed blockHeight,
        bytes32 indexed newBlockHash,
        uint256 newBaseDifficulty
    );

    // Struct for batch parameter retrieval
    struct MiningParams {
        bytes32 lastBlockHash;
        uint256 baseDifficulty;
        uint256 blockHeight;
        uint256 currentReward;
    }

    constructor(
        address _bohriumTokenAddress,
        address _stakedBohrTokenAddress
    ) Ownable(msg.sender) {
        bohriumToken = IBohriumToken(_bohriumTokenAddress);
        stakedBohrToken = IStakedBohrToken(_stakedBohrTokenAddress);
        lastHalvingTimestamp = block.timestamp;
        lastBlockTimestamp = block.timestamp;
        baseDifficulty = type(uint256).max >> 16;
        lastBlockHash = bytes32(0);
    }

    // Setter functions for token references (only owner)
    function setBohriumToken(address _bohriumTokenAddress) external onlyOwner {
        require(_bohriumTokenAddress != address(0), "Invalid address");
        bohriumToken = IBohriumToken(_bohriumTokenAddress);
    }

    function setStakedBohrToken(address _stakedBohrTokenAddress) external onlyOwner {
        require(_stakedBohrTokenAddress != address(0), "Invalid address");
        stakedBohrToken = IStakedBohrToken(_stakedBohrTokenAddress);
    }

    function currentReward() public view returns (uint256) {
        uint256 halvings = blockHeight / HALVING_INTERVAL_BLOCKS;
        uint256 reward = INITIAL_REWARD >> halvings;
        return reward > 1e14 ? reward : 1e14; // Minimum reward of 0.0001 BOHR
    }

    function getMinerDifficulty(address miner) public view returns (uint256) {
        uint256 stakedAmount = stakedBohrToken.getEffectiveBalance(miner);
        uint256 requiredStake = currentReward() * REQUIRED_STAKE_MULTIPLIER;
        uint256 difficulty = baseDifficulty;

        // Apply penalty for unstaked miners (make mining harder)
        if (stakedAmount < requiredStake) {
            // Using unchecked for intentional overflow protection
            unchecked {
                difficulty = difficulty * UNDERSTAKE_PENALTY_MULTIPLIER;
            }
            return difficulty;
        }

        // Calculate stake multiplier benefit
        if (stakedAmount >= requiredStake) {
            // Prevent division by zero and handle small required stakes
            if (requiredStake == 0) return difficulty;

            // Calculate multiplier safely
            uint256 multiplier = (stakedAmount * 100) / requiredStake;
            if (multiplier <= 100) return difficulty;  // No benefit if not over 100%

            // Calculate benefit (5% per 10x stake, capped at 50%)
            uint256 benefit = ((multiplier - 100) * 5) / 100;  // Simplified calculation
            benefit = benefit > 50 ? 50 : benefit;

            // Apply benefit by reducing difficulty
            difficulty = (difficulty * (100 - benefit)) / 100;
        }

        return difficulty;
    }

    // Get all general mining parameters in one call
    function getMiningParams() external view returns (MiningParams memory) {
        return MiningParams({
            lastBlockHash: lastBlockHash,
            baseDifficulty: baseDifficulty,
            blockHeight: blockHeight,
            currentReward: currentReward()
        });
    }

    // Get all parameters including miner-specific difficulty
    function getMinerParams(address miner) external view returns (
        bytes32 _lastBlockHash,
        uint256 _baseDifficulty,
        uint256 _blockHeight,
        uint256 _currentReward,
        uint256 _minerDifficulty
    ) {
        return (
            lastBlockHash,
            baseDifficulty,
            blockHeight,
            currentReward(),
            getMinerDifficulty(miner)
        );
    }

    function submitBlock(uint256 nonce) external {
        uint256 minerDifficulty = getMinerDifficulty(msg.sender);

        bytes32 hash = keccak256(abi.encodePacked(
            msg.sender,
            lastBlockHash,
            minerDifficulty,
            nonce
        ));

        require(uint256(hash) <= minerDifficulty, "Hash doesn't meet difficulty");

        // Calculate block time
        uint256 timeElapsed = block.timestamp - lastBlockTimestamp;

        // Check if difficulty should be adjusted
        adjustDifficulty(timeElapsed);

        // Determine reward recipient (main wallet if delegated)
        address rewardRecipient = msg.sender;
        address mainWallet = stakedBohrToken.delegatedBy(msg.sender);
        if (mainWallet != address(0)) {
            rewardRecipient = mainWallet;
        }

        // Calculate reward before updating state
        uint256 reward = currentReward();

        // Update state before minting reward
        lastBlockHash = hash;
        lastBlockTimestamp = block.timestamp;
        blockHeight++;

        // Mint reward to the appropriate recipient
        bohriumToken.mint(rewardRecipient, reward);

        // Emit the params changed event
        emit MiningParamsChanged(blockHeight, hash, baseDifficulty);

        // Check for halving based on block height
        if (blockHeight % HALVING_INTERVAL_BLOCKS == 0) {
            emit RewardHalved(currentReward());
        }

        emit BlockMined(msg.sender, blockHeight, nonce, reward, timeElapsed, rewardRecipient);
    }

    function adjustDifficulty(uint256 timeElapsed) internal {
        if (blockHeight % DIFFICULTY_ADJUSTMENT_BLOCKS == 0) {
            adjustmentStartTimestamp = block.timestamp;
        }

        lastBlockTimestamp = block.timestamp;

        // Only adjust difficulty at the end of each period
        if ((blockHeight + 1) % DIFFICULTY_ADJUSTMENT_BLOCKS != 0) {
            return;
        }

        // Apply dampening (4x max change) (>> 2 is equivalent to / 4, << 2 is equivalent to * 4)
        timeElapsed = timeElapsed < TARGET_BLOCK_TIME >> 2 ? TARGET_BLOCK_TIME >> 2 : 
                      timeElapsed > TARGET_BLOCK_TIME << 2 ? TARGET_BLOCK_TIME << 2 : 
                      timeElapsed;

        // Calculate new difficulty using actual ratio
        uint256 newDifficulty = (baseDifficulty * timeElapsed) / TARGET_BLOCK_TIME;

        // Apply safety bounds
        uint256 minDifficulty = type(uint256).max >> 32;
        newDifficulty = newDifficulty < minDifficulty ? minDifficulty : newDifficulty;

        baseDifficulty = newDifficulty;
        emit DifficultyAdjusted(baseDifficulty);
    }

    // Add this function for testing purposes only
    function setCurrentDifficulty(uint256 _difficulty) external {
        baseDifficulty = _difficulty;
        emit DifficultyAdjusted(baseDifficulty);
    }

    // Add this function for testing purposes only
    function mintForTesting(address to, uint256 amount) external {
        bohriumToken.mint(to, amount);
    }
}

contracts/BohriumToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";

contract BohriumToken is ERC20, AccessControl {
    bytes32 public constant MINTER_ROLE = keccak256("MINTER_ROLE");

    uint256 public constant UPDATE_DELAY = 2 days;
    address public pendingMinter;
    uint256 public updateTime;
    address public currentMinter;

    event MinterUpdateProposed(address indexed newMinter, uint256 executeTime);
    event MinterUpdateExecuted(address indexed newMinter);
    event MinterUpdateCancelled(address indexed cancelledMinter);

    constructor() ERC20("Bohrium", "BOHR") {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
    }

    function mint(address to, uint256 amount) external onlyRole(MINTER_ROLE) {
        _mint(to, amount);
    }

    // Function to set initial minter (only callable by admin, only if no current minter)
    function setInitialMinter(address _minter) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(currentMinter == address(0), "Minter already set");
        require(_minter != address(0), "Invalid minter address");

        _grantRole(MINTER_ROLE, _minter);
        currentMinter = _minter;
    }

    function proposeMinterUpdate(address _newMinter) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(_newMinter != address(0), "Invalid address");
        require(pendingMinter == address(0), "Update already pending");

        pendingMinter = _newMinter;
        updateTime = block.timestamp + UPDATE_DELAY;

        emit MinterUpdateProposed(_newMinter, updateTime);
    }

    function executeMinterUpdate() external {
        require(block.timestamp >= updateTime, "Update not ready");
        require(pendingMinter != address(0), "No pending update");

        // Revoke old minter if there is one
        if (currentMinter != address(0)) {
            _revokeRole(MINTER_ROLE, currentMinter);
        }

        // Grant new minter
        address newMinter = pendingMinter;
        _grantRole(MINTER_ROLE, newMinter);
        currentMinter = newMinter;
        pendingMinter = address(0);

        emit MinterUpdateExecuted(newMinter);
    }

    function cancelMinterUpdate() external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(pendingMinter != address(0), "No pending update");

        address cancelledMinter = pendingMinter;
        pendingMinter = address(0);
        updateTime = 0;

        emit MinterUpdateCancelled(cancelledMinter);
    }

    // View function to check pending update status
    function getPendingUpdate() external view returns (address pending, uint256 executeTime, bool canExecute) {
        return (pendingMinter, updateTime, block.timestamp >= updateTime && pendingMinter != address(0));
    }
}

contracts/StakedBohrToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";

interface IBohriumMining {
    function blockHeight() external view returns (uint256);
}

contract StakedBohrToken is ERC20, Ownable {
    IERC20 public immutable bohrToken;

    uint256 public constant UNSTAKING_COOLDOWN_BLOCKS = 1000;

    // Reference to the mining contract to access Bohrium block height
    address public miningContract;

    // Mapping to track unstaking requests
    mapping(address => UnstakeRequest) public unstakeRequests;

    // Delegation mappings
    mapping(address => address) public delegatedBy; // session wallet => main wallet
    mapping(address => address) public delegatedTo; // main wallet => session wallet

    // Pending delegations that need to be accepted
    mapping(address => address) public pendingDelegations; // session wallet => main wallet

    struct UnstakeRequest {
        uint256 amount;
        uint256 requestBohriumBlock; // Changed from requestBlock to requestBohriumBlock
    }

    event UnstakeRequested(address indexed user, uint256 amount, uint256 requestBohriumBlock);
    event UnstakeCompleted(address indexed user, uint256 amount);
    event DelegationSet(address indexed sessionWallet, address indexed mainWallet);
    event DelegationRemoved(address indexed sessionWallet, address indexed mainWallet);
    event DelegationRequested(address indexed sessionWallet, address indexed mainWallet);
    event DelegationRequestCancelled(address indexed sessionWallet, address indexed mainWallet);

    constructor(address _bohrToken) ERC20("Staked BOHR", "sBOHR") Ownable(msg.sender) {
        bohrToken = IERC20(_bohrToken);
    }

    // Set the mining contract address (only owner can do this)
    function setMiningContract(address _miningContract) external onlyOwner {
        require(_miningContract != address(0), "Invalid mining contract address");
        miningContract = _miningContract;
    }

    // Get current Bohrium block height
    function getCurrentBohriumBlock() public view returns (uint256) {
        require(miningContract != address(0), "Mining contract not set");
        return IBohriumMining(miningContract).blockHeight();
    }

    // Override transfer functions to make sBOHR non-transferrable
    function _update(address from, address to, uint256 value) internal override {
        if (from != address(0) && to != address(0)) {
            revert("sBOHR: non-transferrable");
        }
        super._update(from, to, value);
    }

    // Stake BOHR for sBOHR
    function stake(uint256 amount) external {
        require(amount > 0, "Cannot stake 0");

        // Transfer BOHR from user to this contract
        bohrToken.transferFrom(msg.sender, address(this), amount);

        // Mint sBOHR to user
        _mint(msg.sender, amount);
    }

    // Request to unstake sBOHR back to BOHR
    function requestUnstake(uint256 amount) external {
        require(amount > 0, "Cannot unstake 0");
        require(balanceOf(msg.sender) >= amount, "Insufficient staked balance");
        require(unstakeRequests[msg.sender].amount == 0, "Unstake already requested");
        require(miningContract != address(0), "Mining contract not set");

        // Lock the tokens by burning them
        _burn(msg.sender, amount);

        // Get current Bohrium block height
        uint256 currentBohriumBlock = getCurrentBohriumBlock();

        // Record the unstake request
        unstakeRequests[msg.sender] = UnstakeRequest({
            amount: amount,
            requestBohriumBlock: currentBohriumBlock
        });

        emit UnstakeRequested(msg.sender, amount, currentBohriumBlock);
    }

    // Complete unstake after cooldown
    function completeUnstake() external {
        UnstakeRequest memory request = unstakeRequests[msg.sender];
        require(request.amount > 0, "No unstake requested");

        // Check if enough Bohrium blocks have passed
        uint256 currentBohriumBlock = getCurrentBohriumBlock();
        require(currentBohriumBlock >= request.requestBohriumBlock + UNSTAKING_COOLDOWN_BLOCKS, 
                "Cooldown not complete");

        // Clear the request
        uint256 amount = request.amount;
        delete unstakeRequests[msg.sender];

        // Return BOHR tokens
        bohrToken.transfer(msg.sender, amount);

        emit UnstakeCompleted(msg.sender, amount);
    }

    // Cancel unstake request
    function cancelUnstake() external {
        UnstakeRequest memory request = unstakeRequests[msg.sender];
        require(request.amount > 0, "No unstake requested");

        // Return sBOHR tokens
        uint256 amount = request.amount;
        delete unstakeRequests[msg.sender];

        _mint(msg.sender, amount);
    }

    // Request delegation from main wallet to session wallet
    function requestDelegation(address sessionWallet) external {
        require(sessionWallet != address(0), "Invalid session wallet");
        require(sessionWallet != msg.sender, "Cannot delegate to self");

        // If already delegated to another session wallet, remove the old delegation first
        if (delegatedTo[msg.sender] != address(0)) {
            address oldSessionWallet = delegatedTo[msg.sender];
            delegatedBy[oldSessionWallet] = address(0);
            delegatedTo[msg.sender] = address(0);
            emit DelegationRemoved(oldSessionWallet, msg.sender);
        }

        // Add this check to prevent circular delegations
        require(delegatedTo[sessionWallet] == address(0), "Circular delegation not allowed");

        // Store the pending delegation request
        pendingDelegations[sessionWallet] = msg.sender;

        emit DelegationRequested(sessionWallet, msg.sender);
    }

    // Accept delegation (must be called by the session wallet)
    function acceptDelegation() external {
        address mainWallet = pendingDelegations[msg.sender];
        require(mainWallet != address(0), "No pending delegation");

        // If this session wallet is already delegated to another main wallet, remove the old delegation first
        if (delegatedBy[msg.sender] != address(0)) {
            address oldMainWallet = delegatedBy[msg.sender];
            delegatedTo[oldMainWallet] = address(0);
            delegatedBy[msg.sender] = address(0);
            emit DelegationRemoved(msg.sender, oldMainWallet);
        }

        // Clear the pending request
        delete pendingDelegations[msg.sender];

        // Set up the delegation
        delegatedBy[msg.sender] = mainWallet;
        delegatedTo[mainWallet] = msg.sender;

        emit DelegationSet(msg.sender, mainWallet);
    }

    // Cancel a pending delegation request (called by main wallet)
    function cancelDelegationRequest(address sessionWallet) external {
        require(pendingDelegations[sessionWallet] == msg.sender, "Not your delegation request");

        delete pendingDelegations[sessionWallet];

        emit DelegationRequestCancelled(sessionWallet, msg.sender);
    }

    // Remove delegation
    function removeDelegation() external {
        address sessionWallet = delegatedTo[msg.sender];
        require(sessionWallet != address(0), "No delegation exists");

        address mainWallet = msg.sender;
        delegatedBy[sessionWallet] = address(0);
        delegatedTo[mainWallet] = address(0);

        emit DelegationRemoved(sessionWallet, mainWallet);
    }

    // Get effective balance including delegations
    function getEffectiveBalance(address account) public view returns (uint256) {
        uint256 directBalance = balanceOf(account);

        // If this is a session wallet, add the main wallet's balance
        address mainWallet = delegatedBy[account];
        if (mainWallet != address(0)) {
            return directBalance + balanceOf(mainWallet);
        }

        return directBalance;
    }
}

